K = 60

def rrf(lists, k=K, top=100):
    """lists: {name: [chunk_id, ...]} best first."""
    score, best = {}, {}
    for name, ids in lists.items():
        for rank, cid in enumerate(ids, start=1):
            score[cid] = score.get(cid, 0.0) + 1.0 / (k + rank)
            best[cid] = min(best.get(cid, rank), rank)
    # tricky part: deterministic ties, best single rank then id
    order = sorted(score, key=lambda c: (-score[c], best[c], c))
    return order[:top], score

async def hybrid_search(req):
    if not req.principals:
        raise NoPrefilter()  # fail closed: never search without a filter
    vec = await embed(req.query)
    async def bm25():
        return await q_lex(req.tenant_id, req.query, req.principals, 100)
    async def dense():
        return await q_vec(req.tenant_id, vec, req.principals, 100)
    res = await asyncio.gather(
        asyncio.wait_for(bm25(), 0.4), asyncio.wait_for(dense(), 0.4),
        return_exceptions=True)
    lists = {n: r for n, r in zip(('bm25', 'dense'), res)
             if not isinstance(r, BaseException)}
    if not lists:
        return []
    ids, score = rrf(lists, top=req.limit)
    return [cand(c, score[c], lists) for c in ids]

