async def live_search(q, apps, tokens, deadline_s=1.5):
    apps = [a for a in apps if breaker.allow(a)][:6]
    results, timed_out = {}, []

    async def one(app):
        try:
            hits = await adapters[app].search(q.text, tokens[app], limit=20)
            breaker.ok(app)
            results[app] = hits
        except asyncio.CancelledError:
            raise
        except Exception:
            breaker.fail(app)

    tasks = {a: asyncio.create_task(one(a)) for a in apps}
    done, pending = await asyncio.wait(tasks.values(), timeout=deadline_s)
    for t in pending:  # tricky part: cancel late apps, keep early ones
        t.cancel()
    timed_out = [a for a, t in tasks.items() if t in pending]
    for a in timed_out:
        breaker.fail(a)
    lists = {a: [h.uri for h in hs] for a, hs in results.items()}
    ids, score = rrf(lists, k=60, top=100)
    by_uri = {h.uri: (a, i + 1, h) for a, hs in results.items() for i, h in enumerate(hs)}
    out = [to_result(by_uri[u], score[u]) for u in ids]
    return LiveOutcome(out, timed_out, [a for a in q.apps if a not in apps])

