async def read_one(p, token, sem):
    async with sem:
        for attempt in (0, 1):
            try:
                async with asyncio.timeout(1.2):
                    r = await http.get(p.fetch_url, headers={
                        'Authorization': f'Bearer {token}',
                        'If-None-Match': p.etag or ''})
                break
            except (asyncio.TimeoutError, httpx.TransportError):
                if attempt == 1:
                    return Fallback(p)  # snippet_fallback state
                await asyncio.sleep(0.15)
    if r.status_code in (403, 404, 410):
        emit('tombstone' if r.status_code != 403 else 'access_lost', p.uri)
        return Dropped(p.uri, str(r.status_code))
    text = cached_passage(p) if r.status_code == 304 else extract(r, p)
    state = 'fresh'
    if r.status_code == 200 and content_hash(text) != p.content_hash:
        state = 'changed'  # tricky part: tell ix_fetch, do not write text here
        emit('stale', p.uri, r.headers.get('ETag'))
    return Passage(p.uri, text[:20000], r.headers.get('ETag', p.etag),
                   now(), p.version, state)

async def hydrate(ptrs, tokens):
    sem = asyncio.Semaphore(10)
    outs = await asyncio.gather(*(read_one(p, tokens[p.app], sem) for p in ptrs))
    return split(outs)

