def run_loop(gw, ctx, scope, q, budget):
    seen, ev = set(), []
    for step in range(budget.steps):
        act = gw.json(model=SMALL, schema=Action, prompt=render(q, ev[-3:]))
        if act.done or budget.tokens_left <= 0:
            break
        hits = CONTROLS[act.control](ctx, scope, **act.args)             # filter applied inside each control
        hits = [h for h in hits if h.id not in seen]
        seen.update(h.id for h in hits)
        ev.extend(trim(hits, 1500)); budget.tokens_left -= tokens(hits)
    return Evidence(ev, steps=step + 1)
